/** A rule of the task that the input broke; the HTTP layer reports it as `validation_failed`. */
export class ValidationError extends Error {}

/**
 * Returns the title as it is stored: trimmed, 1 to 500 characters.
 * Characters are counted as code points, the way SQLite's `length()` counts them in the CHECK constraint.
 */
export function parseTitle(input: unknown): string {
  if (typeof input !== "string") throw new ValidationError("title must be a string");
  if (!input.isWellFormed()) throw new ValidationError("title must be valid Unicode text");
  // Control characters (NUL included, which truncates SQLite's length()) have no place in a one-line title.
  if (/\\p{Cc}/u.test(input.trim())) {
    throw new ValidationError("title must not contain control characters");
  }
  const title = input.trim();
  if (title.length === 0) throw new ValidationError("title must not be empty");
  if ([...title].length > TITLE_MAX_LENGTH) {
    throw new ValidationError(`title must be at most ${TITLE_MAX_LENGTH} characters`);
  }
  return title;
}

export function listTasks''')
